      "path": "src/client/cost.ts",
      "content": "/**\n * Cost estimation for the token pet (pure, dependency-free client module).\n *\n * The plugin only ever sees token counts; converting them into money requires\n * a price table. We ship a small editable default table (USD per 1M tokens),\n * keyed by model name or by trailing-`*` prefix (e.g. `claude-*`), with `*`\n * as the universal fallback. All estimates are explicitly \"估算\" in the UI;\n * the user can replace the whole table in Settings.\n *\n * No model prices are fetched from the network: the table is local, editable\n * and versioned inside the settings document.\n * @module dsh-token-pet/cost\n */\n\nexport interface CostTotals {\n  uncachedInputTokens: number\n  outputTokens: number\n  cacheReadTokens: number\n  cacheWriteTokens: number\n}\n\n/** One (model, day) cell shape compatible with the ledger's byModelDay rows. */\nexport interface CostCell {\n  provider: string\n  model: string\n  day: string\n  totals: CostTotals\n  total: number\n}\n\n/** Per-1M-token rates in USD. Missing keys price at 0. */\nexport interface PriceEntry {\n  input: number\n  output: number\n  cacheRead: number\n  cacheWrite: number\n}\n\nexport type PriceTable = Record<string, PriceEntry>\n\nexport type CostCurrency = 'USD' | 'CNY'\n\n/** Approximate public list prices (USD per 1M tokens). User-editable. */\nexport const DEFAULT_PRICES: PriceTable = {\n  'deepseek-chat': { input: 0.27, cacheRead: 0.07, cacheWrite: 0.27, output: 1.1 },\n  'deepseek-reasoner': { input: 0.55, cacheRead: 0.14, cacheWrite: 0.55, output: 2.19 },\n  'gpt-4o': { input: 2.5, cacheRead: 1.25, cacheWrite: 2.5, output: 10 },\n  'gpt-4o-mini': { input: 0.15, cacheRead: 0.075, cacheWrite: 0.15, output: 0.6 },\n  'gpt-4.1': { input: 2, cacheRead: 0.5, cacheWrite: 2, output: 8 },\n  'o3*': { input: 2, cacheRead: 0.5, cacheWrite: 2, output: 8 },\n  'claude-*': { input: 3, cacheRead: 0.3, cacheWrite: 3.75, output: 15 },\n  'glm-*': { input: 0.5, cacheRead: 0.5, cacheWrite: 0.5, output: 2 },\n  'qwen-*': { input: 0.4, cacheRead: 0.4, cacheWrite: 0.4, output: 1.2 },\n  'kimi-*': { input: 0.6, cacheRead: 0.6, cacheWrite: 0.6, output: 2 },\n  '*': { input: 1, cacheRead: 0.5, cacheWrite: 1, output: 3 },\n}\n\nexport const FALLBACK_PRICE: PriceEntry = { input: 1, cacheRead: 0.5, cacheWrite: 1, output: 3 }\n\nexport const DEFAULT_PRICE_TABLE_JSON = JSON.stringify(DEFAULT_PRICES, null, 2)\n\n/** CNY per USD used only for display conversion when the currency is CNY. */\nexport const DEFAULT_CNY_RATE = 7.2\n\nfunction isNonNegativeNumber(value: unknown): value is number {\n  return typeof value === 'number' && Number.isFinite(value) && value >= 0\n}\n\nfunction parseEntry(value: unknown): PriceEntry | null {\n  if (!value || typeof value !== 'object') return null\n  const v = value as Record<string, unknown>\n  const input = isNonNegativeNumber(v.input) ? v.input : 0\n  const output = isNonNegativeNumber(v.output) ? v.output : 0\n  const cacheRead = isNonNegativeNumber(v.cacheRead) ? v.cacheRead : 0\n  const cacheWrite = isNonNegativeNumber(v.cacheWrite) ? v.cacheWrite : 0\n  if (input === 0 && output === 0 && cacheRead === 0 && cacheWrite === 0) return null\n  return { input, output, cacheRead, cacheWrite }\n}\n\n/**\n * Parse a user-supplied JSON price table. Invalid documents return null and\n * callers fall back to DEFAULT_PRICES; entries with zero rates are dropped.\n */\nexport function parsePriceTable(json: string): PriceTable | null {\n  let parsed: unknown\n  try { parsed = JSON.parse(json) } catch { return null }\n  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null\n  const out: PriceTable = {}\n  for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {\n    if (key === '') continue\n    const entry = parseEntry(value)\n    if (entry) out[key] = entry\n  }\n  return Object.keys(out).length > 0 ? out : null\n}\n\n/**\n * Resolve a model to its price entry: exact key, then longest `*`-suffixed\n * prefix, then the `*` fallback.\n */\nexport function resolvePrice(table: PriceTable, model: string): PriceEntry {\n  const direct = table[model]\n  if (direct) return direct\n  const prefixes = Object.keys(table)\n    .filter((key) => key.endsWith('*') && key.length > 1)\n    .sort((a, b) => b.length - a.length)\n  for (const key of prefixes) {\n    if (model.startsWith(key.slice(0, -1))) return table[key] as PriceEntry\n  }\n  return table['*'] ?? FALLBACK_PRICE\n}\n\n/** USD cost of one token-usage snapshot under a price entry. */\nexport function costOfTotals(totals: CostTotals, price: PriceEntry): number {\n  return (\n    (totals.uncachedInputTokens / 1_000_000) * price.input +\n    (totals.outputTokens / 1_000_000) * price.output +\n    (totals.cacheReadTokens / 1_000_000) * price.cacheRead +\n    (totals.cacheWriteTokens / 1_000_000) * price.cacheWrite\n  )\n}\n\n/** USD cost of a cell row under a table. */\nexport function costOfCell(cell: CostCell, table: PriceTable): number {\n  return costOfTotals(cell.totals, resolvePrice(table, cell.model))\n}\n\n/** Skip structurally incomplete cells defensively (host/fixture tolerance). */\nfunction isUsableCell(cell: CostCell): boolean {\n  return typeof cell?.model === 'string' && cell.model !== '' && typeof cell?.day === 'string' && cell.day !== ''\n}\n\nexport interface MonthKey { year: number; month: number; prefix: string }\n\n/** Local-time month prefix (\"YYYY-MM\") matching the ledger's day strings. */\nexport function monthKeyOf(now = Date.now()): MonthKey {\n  const d = new Date(now)\n  const year = d.getFullYear()\n  const month = d.getMonth() + 1\n  return { year, month, prefix: `${year}-${String(month).padStart(2, '0')}` }\n}\n\n/** USD cost of every cell whose day falls in the current local month. */\nexport function monthlyCostOfCells(cells: readonly CostCell[], table: PriceTable, now = Date.now()): number {\n  const prefix = monthKeyOf(now).prefix\n  let total = 0\n  for (const cell of cells) if (isUsableCell(cell) && cell.day.startsWith(prefix)) total += costOfCell(cell, table)\n  return total\n}\n\n/** Per-(provider, model) accumulated token totals and estimated cost. */\nexport interface ModelCostRow {\n  provider: string\n  model: string\n  total: number\n  cost: number\n}\n\n/** Roll cells into per-model rows with estimated cost, descending total. */\nexport function costPerModel(cells: readonly CostCell[], table: PriceTable): ModelCostRow[] {\n  const map = new Map<string, ModelCostRow>()\n  for (const cell of cells) {\n    if (!isUsableCell(cell)) continue\n    const key = `${cell.provider}\\u0000${cell.model}`\n    const row = map.get(key) ?? { provider: cell.provider, model: cell.model, total: 0, cost: 0 }\n    row.total += cell.total\n    row.cost += costOfCell(cell, table)\n    map.set(key, row)\n  }\n  return [...map.values()].sort((a, b) => b.total - a.total)\n}\n\n/** Per-day totals from ledger cells (only days with usage), newest first. */\nexport function dayTotalsOfCells(cells: readonly CostCell[]): Array<{ day: string; total: number; cells: number }> {\n  const map = new Map<string, { day: string; total: number; cells: number }>()\n  for (const cell of cells) {\n    if (!isUsableCell(cell)) continue\n    const row = map.get(cell.day) ?? { day: cell.day, total: 0, cells: 0 }\n    row.total += cell.total\n    row.cells += 1\n    map.set(cell.day, row)\n  }\n  return [...map.values()].sort((a, b) => (a.day < b.day ? 1 : a.day > b.day ? -1 : 0))\n}\n\n/** Format an estimated cost for display (USD or CNY). */\nexport function formatCost(usd: number, currency: CostCurrency = 'USD', cnyRate = DEFAULT_CNY_RATE): string {\n  if (!Number.isFinite(usd) || usd < 0) return '—'\n  if (currency === 'CNY') return `¥${(usd * cnyRate).toFixed(2)}`\n  return `$${usd.toFixed(2)}`\n}\n\nexport function isCostCurrency(value: unknown): value is CostCurrency {\n  return value === 'USD' || value === 'CNY'\n}\n\n// ---- Visual price editor draft helpers (pure, UI-agnostic) ----\n\n/** One editable price row in the Settings price editor. Values are strings so\n * the input fields never fight the user mid-typing; validation happens on save. */\nexport interface PriceDraftRow {\n  id: string\n  /** Model name or `*`-suffixed prefix (e.g. \"deepseek-chat\", \"claude-*\"). */\n  key: string\n  input: string\n  cacheRead: string\n  cacheWrite: string\n  output: string\n}\n\nfunction numberString(n: number): string {\n  return Number.isFinite(n) ? String(n) : '0'\n}\n\n/** Turn a persisted price-table JSON into editable rows (newest order kept). */\nexport function priceRowsFromJson(json: string): PriceDraftRow[] {\n  const table = parsePriceTable(json) ?? DEFAULT_PRICES\n  return Object.entries(table).map(([key, entry], index) => ({\n    id: `${index}-${key}`,\n    key,\n    input: numberString(entry.input),\n    cacheRead: numberString(entry.cacheRead),\n    cacheWrite: numberString(entry.cacheWrite),\n    output: numberString(entry.output),\n  }))\n}\n\nfunction isNonNegativeString(value: string): boolean {\n  return value.trim() !== '' && Number.isFinite(Number(value)) && Number(value) >= 0\n}\n/** Export for UI input validation (used by the price editor to flag bad rows). */\nexport { isNonNegativeString }\n\n/** Validate rows: a row is valid when its key is non-empty and all four rates\n * are non-negative numbers. Returns the buildable table and the invalid rows. */\nexport function tableFromDraftRows(rows: readonly PriceDraftRow[]): { table: PriceTable; invalid: PriceDraftRow[] } {\n  const table: PriceTable = {}\n  const invalid: PriceDraftRow[] = []\n  for (const row of rows) {\n    const key = row.key.trim()\n    // A bare `*` is the universal fallback; otherwise an alphanumeric start\n    // with letters/digits/._- and an optional trailing `*` prefix wildcard.\n    const validKey = key === '*' || /^[a-z0-9][a-z0-9._-]*\\*?$/i.test(key)\n    if (!validKey || !isNonNegativeString(row.input) || !isNonNegativeString(row.output) ||\n      !isNonNegativeString(row.cacheRead) || !isNonNegativeString(row.cacheWrite)) {\n      invalid.push(row)\n      continue\n    }\n    table[key] = {\n      input: Number(row.input),\n      output: Number(row.output),\n      cacheRead: Number(row.cacheRead),\n      cacheWrite: Number(row.cacheWrite),\n    }\n  }\n  return { table, invalid }\n}\n\n/** Serialize valid draft rows back to the persisted JSON form (stable key order). */\nexport function draftRowsToJson(rows: readonly PriceDraftRow[]): { json: string | null; invalid: PriceDraftRow[] } {\n  const { table, invalid } = tableFromDraftRows(rows)\n  if (Object.keys(table).length === 0) return { json: null, invalid: rows as PriceDraftRow[] }\n  return { json: JSON.stringify(table, null, 2), invalid }\n}\n"
    },
    {
      "path": "src/client/prompt-panel.tsx",
      "content": "import { createElement as h, useEffect, useLayoutEffect, useRef, useState } from 'react'\nimport { createPromptEnhancer, type EnhancementAction, type EnhancementResult, type PromptEnhancerAdapter } from './prompt.ts'\nimport { loadSettings, saveSettings, resolveEnhancementTemplate } from './settings.ts'\nimport { useSettings } from './settings-hook.ts'\nimport { translate, type Language } from './i18n.ts'\nimport { promptMessages, promptErrorMessage, PromptEnhancementError } from './prompt-messages.ts'\n\n/** Visible opt-in enhancement UI. The composer owns actual apply/send semantics. */\ntype PromptPanelAction = EnhancementAction | 'prompt-enhancing' | 'prompt-ready' | 'send'\nconst promptCard = { marginTop: 12, padding: 12, border: '1px solid var(--tp-border-strong)', borderRadius: 12, background: 'var(--tp-panel-bg)', boxShadow: 'var(--tp-shadow)', color: 'var(--tp-text)' }\nconst promptHeader = { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, marginBottom: 8 }\nconst promptTitle = { color: 'var(--tp-text)', fontSize: 12, fontWeight: 600, letterSpacing: '.01em' }\nconst promptHint = { color: 'var(--tp-text-2)', fontSize: 10 }\nconst editorStyle = { width: '100%', boxSizing: 'border-box' as const, resize: 'vertical' as const, display: 'block', padding: '8px 9px', borderRadius: 8, border: '1px solid var(--tp-border-strong)', background: 'var(--tp-card-bg)', color: 'var(--tp-text)', caretColor: 'var(--tp-accent)', fontFamily: 'inherit', fontSize: 12, lineHeight: 1.5, outline: 'none' }\nconst secondaryButton = { color: '#e8eaf2', background: 'rgba(124,150,255,.1)', border: '1px solid rgba(145,167,255,.38)', borderRadius: 7, padding: '5px 9px', fontSize: 11, cursor: 'pointer', transition: 'background .15s ease, border-color .15s ease' }\nconst primaryButton = { ...secondaryButton, color: '#ffffff', background: 'linear-gradient(135deg, #627cff, #8069d9)', borderColor: 'rgba(180,190,255,.72)', fontWeight: 600 }\nexport function PromptEnhancerPanel(p: {\n  language?: Language\n  initial?: string\n  provider?: string\n  model?: string\n  adapter?: PromptEnhancerAdapter\n  onApply?: (text: string) => void\n  onCopy?: (text: string) => void\n  onSend?: (text: string) => void | Promise<void>\n  onAction?: (action: PromptPanelAction) => void\n  /** Drawer chrome is owned by this component so its complete workflow stays mounted while hidden. */\n  drawer?: boolean\n  onClose?: () => void\n}) {\n  const initialText = p.initial ?? ''\n  const [original, setOriginal] = useState(initialText)\n  const [preview, setPreview] = useState<string | null>(null)\n  const [enhancedApplied, setEnhancedApplied] = useState(false)\n  const [sent, setSent] = useState(false)\n  const [error, setError] = useState<unknown>(null)\n  const [copied, setCopied] = useState(false)\n  const [busy, setBusy] = useState(false)\n  const [sending, setSending] = useState(false)\n  const settings = useSettings()\n  const language = p.language ?? settings.language\n  const enhancementEnabled = settings.enhancementEnabled\n  const t = (key: keyof typeof promptMessages) => translate(language, promptMessages, key)\n  const originalBeforeEnhancement = useRef(initialText)\n  // DSH publishes composer drafts asynchronously. While the user is typing,\n  // never let a stale projection overwrite the controlled textarea or cursor.\n  const editingOriginal = useRef(false)\n  const previewRef = useRef<HTMLTextAreaElement | null>(null)\n  const previousPreview = useRef<string | null>(null)\n  const previewFocusPending = useRef(false)\n  // The owner keys this panel by the committed feed generation. Ignore async\n  // completions (including animation events) after that session UI unmounts.\n  const lifetime = useRef<object | null>(null)\n  useLayoutEffect(() => {\n    lifetime.current = {}\n    return () => { lifetime.current = null }\n  }, [])\n\n  // The initial composer draft is captured once on mount. Subsequent drafts are\n  // published by this panel and must never replace text the user is editing.\n\n  // After generation, place the caret in the enhanced result so the user can\n  // continue editing without being sent back to the source textarea.\n  useEffect(() => {\n    if (preview === null) {\n      previousPreview.current = null\n      previewFocusPending.current = false\n      return\n    }\n    if (previousPreview.current === null) previewFocusPending.current = true\n    previousPreview.current = preview\n    if (previewFocusPending.current && !busy && !sending) {\n      previewRef.current?.focus()\n      previewFocusPending.current = false\n    }\n  }, [preview, busy, sending])\n\n  // Keep controller construction out of every render. This panel is mounted\n  // alongside the live projections and otherwise gets re-rendered frequently.\n  const controller = useRef<ReturnType<typeof createPromptEnhancer> | null>(null)\n  if (controller.current === null) controller.current = createPromptEnhancer(p.adapter)\n  const enhancer = controller.current\n  const run = async () => {\n    const token = lifetime.current\n    const source = preview !== null ? preview : original\n    if (!token || !source.trim() || busy || sending || sent) return\n    if (preview === null) originalBeforeEnhancement.current = original\n    p.onAction?.('prompt-enhancing')\n    setBusy(true)\n    setError(null)\n    setSent(false)\n    try {\n      const settings = loadSettings()\n      const result: EnhancementResult = await enhancer.enhance(source, {\n        template: resolveEnhancementTemplate(settings),\n        provider: p.provider,\n        model: settings.enhancementModel || p.model,\n      })\n      if (lifetime.current !== token) return\n      setPreview(result.enhanced)\n      setEnhancedApplied(false)\n      p.onAction?.('prompt-ready')\n    } catch (e) {\n      if (lifetime.current === token) setError(e)\n    } finally {\n      if (lifetime.current === token) setBusy(false)\n    }\n  }\n\n  const applyToComposer = (text: string) => {\n    try { p.onApply?.(text) }\n    catch (e) { setError(e) }\n  }\n\n  const apply = (text: string | null, action: EnhancementAction) => {\n    if (!lifetime.current || text === null || sent) return\n    p.onAction?.(action)\n    setOriginal(text)\n    setEnhancedApplied(action === 'replace')\n    setError(null)\n    applyToComposer(text)\n  }\n\n  const revert = () => {\n    if (!lifetime.current || sent || sending) return\n    const text = originalBeforeEnhancement.current\n    p.onAction?.('cancel')\n    setOriginal(text)\n    setEnhancedApplied(false)\n    setError(null)\n    applyToComposer(text)\n  }\n\n  const send = async () => {\n    const token = lifetime.current\n    if (!token || !preview?.trim() || sending || busy || sent || !p.onSend) return\n    setSending(true)\n    setError(null)\n    try {\n      p.onAction?.('send')\n      // onSend is wired to DSH inputActions, not an HTTP endpoint.\n      await p.onSend(preview)\n      if (lifetime.current !== token) return\n      setOriginal(preview)\n      setEnhancedApplied(true)\n      setSent(true)\n    } catch (e) {\n      if (lifetime.current === token) setError(e)\n    } finally {\n      if (lifetime.current === token) setSending(false)\n    }\n  }\n\n  const editOriginal = (text: string) => {\n    if (!lifetime.current) return\n    // Keep keystrokes local. Calling the host composer on every character can\n    // publish a parent snapshot and disturb the controlled textarea/caret.\n    editingOriginal.current = true\n    setOriginal(text)\n    setEnhancedApplied(false)\n  }\n  const commitOriginal = () => {\n    if (!lifetime.current || sent) return\n    applyToComposer(original)\n    editingOriginal.current = false\n  }\n\n  const copy = async () => {\n    const token = lifetime.current\n    if (!token || preview === null) return\n    setError(null); setCopied(false)\n    try {\n      p.onAction?.('copy')\n      if (p.onCopy) await p.onCopy(preview)\n      else if (typeof navigator !== 'undefined' && navigator.clipboard) await navigator.clipboard.writeText(preview)\n      else throw new PromptEnhancementError('clipboard')\n      if (lifetime.current === token) setCopied(true)\n    } catch (e) { if (lifetime.current === token) setError(e) }\n  }\n  const button = (primary = false) => ({ type: 'button' as const, style: primary ? primaryButton : secondaryButton })\n  return h('section', { 'aria-label': t('title'), style: { ...promptCard, minWidth: 0, overflowWrap: 'anywhere', ...(p.drawer ? { marginTop: 0, minHeight: 0, border: 0, borderRadius: 0, boxShadow: 'none', background: 'transparent' } : {}) } }, [\n    h('div', { key: 'header', style: promptHeader }, [\n      h('div', { key: 'heading', style: { display: 'flex', flexDirection: 'column', minWidth: 0 } }, [\n        h('span', { key: 'title', style: promptTitle }, t('title')),\n        h('span', { key: 'hint', style: promptHint }, t(sent ? 'sent' : preview !== null ? 'editable' : 'manual')),\n      ]),\n      p.onClose ? h('button', { key: 'close', type: 'button', onClick: p.onClose, 'aria-label': t('closeAria'), style: { ...secondaryButton, padding: '4px 8px', flex: 'none' } }, t('close')) : null,\n    ]),\n    h('textarea', {\n      key: 'input', value: original,\n      onFocus: () => { editingOriginal.current = true }, onBlur: commitOriginal,\n      onChange: (e: { target: { value: string } }) => editOriginal(e.target.value),\n      placeholder: t('placeholder'), rows: 3,\n      'aria-label': t('original'), style: editorStyle,\n      disabled: sent || busy || sending,\n    }),\n    h('div', { key: 'privacy', style: { marginTop: 6, color: 'var(--tp-text-2)', fontSize: 10, lineHeight: 1.45 } }, [\n      t('privacy'),\n      !enhancementEnabled ? h('button', { key: 'enable', ...button(), onClick: () => { saveSettings({ enhancementEnabled: true }) }, style: { ...secondaryButton, marginLeft: 6 } }, t('enable')) : null,\n    ]),\n    preview !== null ? h('textarea', {\n      key: 'preview', ref: previewRef, value: preview, onChange: (e: { target: { value: string } }) => { setPreview(e.target.value); setEnhancedApplied(false); setCopied(false) },\n      'aria-label': t('preview'), rows: 5, disabled: sent || sending || busy,\n      style: { ...editorStyle, marginTop: 8, borderColor: 'var(--tp-border-strong)', background: 'var(--tp-card-bg)' },\n    }) : null,\n    h('div', { key: 'buttons', style: { display: 'flex', gap: 5, marginTop: 5, flexWrap: 'wrap' } }, [\n      h('button', { key: 'enhance', ...button(true), onClick: run, disabled: !enhancementEnabled || busy || sending || sent || !original.trim() }, t(busy ? 'busy' : 'title')),\n      preview !== null ? h('button', { key: 'replace', ...button(), onClick: () => apply(preview, 'replace'), disabled: busy || sending || sent }, t(enhancedApplied ? 'applied' : 'replace')) : null,\n      preview !== null ? h('button', { key: 'append', ...button(), onClick: () => apply(`${original}\\n\\n${preview}`, 'append'), disabled: busy || sending || sent }, t('append')) : null,\n      preview !== null ? h('button', { key: 'copy', ...button(), onClick: () => void copy(), disabled: sending || busy }, t('copy')) : null,\n      preview !== null ? h('button', { key: 'regenerate', ...button(), onClick: run, disabled: !enhancementEnabled || busy || sending || sent }, t('regenerate')) : null,\n      preview !== null ? h('button', { key: 'revert', ...button(), onClick: revert, disabled: busy || sending || sent }, t(sent ? 'irrevocable' : 'revert')) : null,\n      preview !== null ? h('button', { key: 'send', ...button(true), onClick: () => void send(), disabled: busy || sending || sent || !p.onSend || !preview.trim() }, t(sending ? 'sending' : 'send')) : null,\n    ]),\n    copied ? h('div', { key: 'copied', role: 'status' }, t('copied')) : null,\n    sent ? h('div', { key: 'sent', role: 'status', style: { marginTop: 5, color: 'var(--tp-success)' } }, t('sentDetail')) : null,\n    error !== null ? h('div', { key: 'error', role: 'alert', style: { color: 'var(--tp-danger)', marginTop: 5 } }, promptErrorMessage(error, language)) : null,\n  ])\n}\n"
    },
